import java.util.*;

class Solution {
  private int area(int[][] g, int r1, int r2, int c1, int c2) {
    int minR = r2, maxR = r1 - 1, minC = c2, maxC = c1 - 1;
    for (int r = r1; r < r2; r++)
      for (int c = c1; c < c2; c++)
        if (g[r][c] == 1) {
          minR = Math.min(minR, r);
          maxR = Math.max(maxR, r);
          minC = Math.min(minC, c);
          maxC = Math.max(maxC, c);
        }
    return maxR < minR ? 0 : (maxR - minR + 1) * (maxC - minC + 1);
  }

  public int minimumSum(int[][] grid) {
    int m = grid.length, n = grid[0].length, ans = Integer.MAX_VALUE;
    for (int a = 1; a < m; a++)
      for (int b = a + 1; b < m; b++)
        ans =
            Math.min(ans, area(grid, 0, a, 0, n) + area(grid, a, b, 0, n) + area(grid, b, m, 0, n));
    for (int a = 1; a < n; a++)
      for (int b = a + 1; b < n; b++)
        ans =
            Math.min(ans, area(grid, 0, m, 0, a) + area(grid, 0, m, a, b) + area(grid, 0, m, b, n));
    for (int cut = 1; cut < m; cut++) {
      for (int split = 1; split < n; split++) {
        ans =
            Math.min(
                ans,
                area(grid, 0, cut, 0, split)
                    + area(grid, 0, cut, split, n)
                    + area(grid, cut, m, 0, n));
        ans =
            Math.min(
                ans,
                area(grid, 0, cut, 0, n)
                    + area(grid, cut, m, 0, split)
                    + area(grid, cut, m, split, n));
      }
    }
    for (int cut = 1; cut < n; cut++) {
      for (int split = 1; split < m; split++) {
        ans =
            Math.min(
                ans,
                area(grid, 0, split, 0, cut)
                    + area(grid, split, m, 0, cut)
                    + area(grid, 0, m, cut, n));
        ans =
            Math.min(
                ans,
                area(grid, 0, m, 0, cut)
                    + area(grid, 0, split, cut, n)
                    + area(grid, split, m, cut, n));
      }
    }
    return ans;
  }
}
